import numpy as np

# 定义数据结构
score_type = np.dtype({
    &#39;names&#39;: [&#39;name&#39;, &#39;chinese&#39;, &#39;english&#39;, &#39;math&#39;],
    &#39;formats&#39;: [&#39;S32&#39;, &#39;f&#39;, &#39;f&#39;, &#39;f&#39;]
})
# 创建对象
score = np.array([
    (&#39;zhangfei&#39;, 66, 65, 30),
    (&#39;guangyu&#39;, 95, 85, 98),
    (&#39;zhaoyun&#39;, 93, 92, 96),
    (&#39;huangzhong&#39;, 90, 88, 77),
    (&#39;dianwei&#39;, 80, 90, 90)
], dtype=score_type)

# 平均成绩
for stu in score:
    print(&#39;姓名：%s | 平均成绩：%f&#39; % (stu[0], sum((list(stu)[1::])) &#47; 3))

# 每位同学最低&#47;最高成绩
for stu in score:
    print(&#39;姓名：%s | 最低成绩：%f | 最高成绩：%f&#39; 
          % (stu[0], min(list(stu)[1::]), max(list(stu)[1::])))

# 每位同学各科成绩的方差与标准差
for stu in score:
    print(&#39;姓名：%s | 分数方差：%f | 分数标准差：%f&#39; 
         % (stu[0], np.var(np.array(list(stu)[1::])), np.std(np.array(list(stu)[1::]))))

# 按总成绩排序输出（从小到大）
sumscore_type = np.dtype({
    &#39;names&#39;: [&#39;name&#39;, &#39;total&#39;],
    &#39;formats&#39;: [&#39;S32&#39;, &#39;f&#39;]
})
sumscore = np.array([
    tuple([stu[0], sum(list(stu)[1::])]) for stu in score
], dtype=sumscore_type)
print(np.sort(sumscore, order=&#39;total&#39;))

